fn fibonacci(n: usize) -> Vec<i32> {
    let mut fibs = Vec::with_capacity(n);
    if n >= 1 {
        fibs.push(0);
    }
    if n >= 2 {
        fibs.push(1);
        for i in 2..n {
            // Safe to add without overflow by the problem's assumption.
            let next = fibs[i - 1] + fibs[i - 2];
            fibs.push(next);
        }
    }
    fibs
}

